{
  "probability": 0.74,
  "range_low": 0.68,
  "range_high": 0.80,
  "summary": [
    "Anchor the forecast to the IOM Missing Migrants Project reference class; anchor probability set at 0.65 based on February 2026 pace and historical toll context.",
    "Current year-to-date mortality pace is strong, implying a plausible path to 1,000+ deaths before May if the trend continues.",
    "Seasonal spring crossing dynamics and weather-influenced risk push the probability upward, while improvements in SAR capacity or stricter policy deterrence push it downward.",
    "Final calibrated probability: 0.74 with a range roughly 0.68–0.80 to reflect calibration uncertainty."
  ],
  "confidence": "high",
  "narrative": "Starting from the IOM reference-class anchor of roughly 2,000–2,500 annual Mediterranean deaths and the ~606 deaths by February 2026, the pace suggests a credible chance of surpassing 1,000 by May. Upward pressure from pace and spring conditions is balanced by potential SAR improvements and deterrence, yielding a calibrated posterior around 0.74 with modest uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class: IOM Missing Migrants Project annual Mediterranean death tolls; anchor probability drawn from forecast evidence indicating a high but not certain baseline (Feb 2026 pace ~606 deaths in two months)."
    },
    "factor_updates": [
      {
        "factor": "Current year-to-date mortality pace",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths in the first two months implies a trajectory potentially exceeding 1,000 by end-April if the pace persists."
      },
      {
        "factor": "March–April weather/sea conditions in the Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Spring patterns often increase crossing activity and fatalities, increasing the likelihood of reaching 1,000 before May."
      },
      {
        "factor": "Search-and-rescue capacity and policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Enhanced SAR or restrictive policies can reduce fatalities, mitigating the pace-driven risk."
      },
      {
        "factor": "Policy enforcement and deterrence affecting crossing flows",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter controls may reduce crossing attempts and associated deaths, dampening the path to 1,000."
      },
      {
        "factor": "Reporting lag and data revisions in IOM Missing Migrants Project",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Initial counts can be revised upward, adding uncertainty but not a clear directional push."
      }
    ],
    "synthesis_rationale": "Starting from a 0.65 anchor, I added positive updates for pace and seasonality and subtracted value from SAR/policy factors, with a small neutral datapoint for reporting lag. The calibration leaned toward a moderate-to-high probability, arriving at 0.74 with a measured uncertainty band (0.68–0.80) to reflect data volatility and potential revisions."
  }
}

